use std::path::{Path,PathBuf};
use std::process::{Command,Output};
use std::sync::atomic::{AtomicUsize,Ordering};
use dlm_network_proof::{check_bundle,NetworkBudget,NetworkCertificate,sha256};
static SERIAL:AtomicUsize=AtomicUsize::new(0);
fn root()->PathBuf{Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")}
struct Work(PathBuf);
impl Work{fn new()->Self{let p=std::env::temp_dir().join(format!("dlm-network-protocol-{}-{}",std::process::id(),SERIAL.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&p).unwrap();Self(p)}fn path(&self,name:&str)->PathBuf{self.0.join(name)}}
impl Drop for Work{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn schema()->PathBuf{root().join("crates/dlm_core/tests/native_hosts/dln_state_schema.dlm")}
fn suffix(path:&Path,suffix:&str)->PathBuf{PathBuf::from(format!("{}{suffix}",path.display()))}
fn generate(input:&Path,out:&Path,extra:&[&str])->Output{Command::new(env!("CARGO_BIN_EXE_dlm")).arg("network-protocol").arg(input).args(["--module","generated.protocol","--prefix","Protocol","--lib"]).arg(root().join("lib")).arg("-o").arg(out).args(extra).env_remove("DLM_PATH").output().unwrap()}
fn passed(result:Output){assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));}
#[test]
fn generated_bundle_reproduces_and_passes_the_independent_kernel(){let w=Work::new();let out=w.path("protocol.dlm");passed(generate(&schema(),&out,&[]));passed(generate(&schema(),&out,&["--check"]));let report=check_bundle(&suffix(&out,".nproof"),&root().join("lib"),None,NetworkBudget::default()).unwrap();assert_eq!(report.model_verified,416);assert_eq!(report.runtime_pending,431);let renamed=w.path("certificate.data");std::fs::copy(suffix(&out,".nproof"),&renamed).unwrap();passed(Command::new(env!("CARGO_BIN_EXE_dlm")).arg("proof-check").arg(&renamed).arg("--lib").arg(root().join("lib")).output().unwrap());let arithmetic=w.path("arithmetic.nproof");std::fs::copy(root().join("examples/native/fixtures/network-spec-zero.kproof"),&arithmetic).unwrap();let legacy=Command::new(env!("CARGO_BIN_EXE_dlm")).arg("proof-check").arg(arithmetic).output().unwrap();assert!(legacy.status.success());assert!(String::from_utf8_lossy(&legacy.stdout).contains("mathematical Nat"));let other=w.path("other.dlm");passed(generate(&suffix(&out,".dns"),&other,&[]));for ext in ["",".dns",".state"]{assert_eq!(std::fs::read(suffix(&out,ext)).unwrap(),std::fs::read(suffix(&other,ext)).unwrap());}}
#[test]
fn changed_source_cannot_receive_a_certificate_by_rebinding_its_digest(){let w=Work::new();let out=w.path("protocol.dlm");passed(generate(&schema(),&out,&[]));let path=suffix(&out,".nproof");let mut proof=NetworkCertificate::from_text(&std::fs::read_to_string(&path).unwrap(),NetworkBudget::default()).unwrap();let source=std::fs::read_to_string(&out).unwrap().replace("return protocol_adopt(move transport,Protocol_spec(),Protocol_machine(),1,initiator);","return protocol_adopt(move transport,Protocol_spec(),Protocol_machine(),0,initiator);");std::fs::write(&out,&source).unwrap();proof.source_sha256=sha256(source.as_bytes());std::fs::write(&path,proof.to_text()).unwrap();assert!(check_bundle(&path,&root().join("lib"),None,NetworkBudget::default()).unwrap_err().message.contains("admitted executable rules"));}
#[test]
fn refusal_and_search_exhaustion_are_atomic_for_existing_bundles(){let w=Work::new();let out=w.path("protocol.dlm");passed(generate(&schema(),&out,&[]));let paths=["",".dns",".state",".nproof"].iter().map(|s|suffix(&out,s)).collect::<Vec<_>>();let mut source=std::fs::read(&out).unwrap();source.extend_from_slice(b"\n// changed\n");std::fs::write(&out,source).unwrap();let old=paths.iter().map(|p|std::fs::read(p).unwrap()).collect::<Vec<_>>();for extra in [vec!["--check"],vec![],vec!["--force","--work","0"]]{let result=generate(&schema(),&out,&extra);assert!(!result.status.success());if extra.contains(&"--work"){assert_eq!(result.status.code(),Some(3));}assert_eq!(old,paths.iter().map(|p|std::fs::read(p).unwrap()).collect::<Vec<_>>());}}
#[test]
fn proof_required_mode_and_invalid_custom_lifecycles_are_refused(){let w=Work::new();let source=w.path("strict.dns");let out=w.path("protocol.dlm");let mut bytes=std::fs::read(root().join("crates/dlm_core/tests/native_hosts/generated/state_session.dlm.dns")).unwrap();bytes[128..132].copy_from_slice(&2u32.to_be_bytes());std::fs::write(&source,bytes).unwrap();let result=generate(&source,&out,&[]);assert!(!result.status.success());assert!(String::from_utf8_lossy(&result.stderr).contains("proof-required"));assert!(!out.exists());let input=w.path("bad.dlm");let mut text=std::fs::read_to_string(schema()).unwrap();let position=text.rfind('}').unwrap();text.insert_str(position,"fn network_machine()->ProtocolMachine guarantees(NoAlloc,NoBlocking,NoIO,BoundedWork){let spec:NetworkSpec=network_schema();let mut machine:ProtocolMachine=protocol_default(&spec,1);machine.transitions[0].roles=1;return machine;}\n");std::fs::write(&input,text).unwrap();let result=generate(&input,&out,&[]);assert!(!result.status.success());assert!(!out.exists());}
#[test]
fn binary_identity_binding_requires_the_exact_supplied_artifact(){let w=Work::new();let source=w.path("protocol.dlm");passed(generate(&schema(),&source,&[]));let proof=suffix(&source,".nproof");let binary=w.path("artifact.bin");std::fs::write(&binary,b"artifact identity only").unwrap();passed(Command::new(env!("CARGO_BIN_EXE_dlm")).arg("network-bind").arg(&proof).arg("--lib").arg(root().join("lib")).arg("--binary").arg(&binary).output().unwrap());let report=check_bundle(&proof,&root().join("lib"),Some(&binary),NetworkBudget::default()).unwrap();assert_eq!(report.binary_sha256,Some(sha256(b"artifact identity only")));assert!(check_bundle(&proof,&root().join("lib"),None,NetworkBudget::default()).is_err());std::fs::write(&binary,b"changed artifact").unwrap();assert!(check_bundle(&proof,&root().join("lib"),Some(&binary),NetworkBudget::default()).is_err());}
